-- PostgreSQL 17 standalone schema.
-- All primary keys and foreign keys are declared inside CREATE TABLE; no ALTER TABLE is required.

CREATE TABLE "users" (
    "user_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "email" VARCHAR(255),
    "nickname" VARCHAR(30) NOT NULL,
    "profile_img" CHAR(7) NOT NULL DEFAULT '#6F9FC6',
    "status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    "last_login_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ(6),
    CONSTRAINT "PK_USERS" PRIMARY KEY ("user_id")
);

CREATE TABLE "page_templates" (
    "template_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" VARCHAR(100) NOT NULL,
    "template_version" VARCHAR(30) NOT NULL,
    "name" VARCHAR(100) NOT NULL,
    "category" VARCHAR(30) NOT NULL,
    "orientation" VARCHAR(20) NOT NULL DEFAULT 'LANDSCAPE',
    "canvas_width" NUMERIC(10, 2) NOT NULL,
    "canvas_height" NUMERIC(10, 2) NOT NULL,
    "default_config" JSONB,
    "display_order" INTEGER NOT NULL DEFAULT 0,
    "is_active" BOOLEAN NOT NULL DEFAULT TRUE,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_PAGE_TEMPLATES" PRIMARY KEY ("template_id")
);

CREATE TABLE "diaries" (
    "diary_id" UUID NOT NULL,
    "owner_user_id" BIGINT,
    "owner_device_id" VARCHAR(64),
    "title" VARCHAR(100) NOT NULL,
    "cover_color" CHAR(7) NOT NULL DEFAULT '#CED9EE',
    "cover_style" VARCHAR(30) NOT NULL DEFAULT 'PLAIN',
    "visibility" VARCHAR(20) NOT NULL DEFAULT 'PRIVATE',
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ(6),
    CONSTRAINT "PK_DIARIES" PRIMARY KEY ("diary_id"),
    CONSTRAINT "FK_users_TO_diaries_1"
        FOREIGN KEY ("owner_user_id") REFERENCES "users" ("user_id")
);

CREATE TABLE "media_files" (
    "media_file_id" UUID NOT NULL,
    "owner_user_id" BIGINT,
    "owner_device_id" VARCHAR(64),
    "media_type" VARCHAR(20) NOT NULL DEFAULT 'IMAGE',
    "source_type" VARCHAR(20) NOT NULL DEFAULT 'UPLOAD',
    "source_media_file_id" UUID,
    "library_category" VARCHAR(20) NOT NULL DEFAULT 'PHOTO',
    "storage_key" VARCHAR(500) NOT NULL,
    "original_filename" VARCHAR(255),
    "mime_type" VARCHAR(100) NOT NULL,
    "file_size" BIGINT NOT NULL,
    "width" INTEGER,
    "height" INTEGER,
    "checksum_sha256" CHAR(64),
    "status" VARCHAR(20) NOT NULL DEFAULT 'UPLOADING',
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ(6),
    CONSTRAINT "PK_MEDIA_FILES" PRIMARY KEY ("media_file_id"),
    CONSTRAINT "FK_users_TO_media_files_1"
        FOREIGN KEY ("owner_user_id") REFERENCES "users" ("user_id"),
    CONSTRAINT "FK_media_files_TO_media_files_1"
        FOREIGN KEY ("source_media_file_id") REFERENCES "media_files" ("media_file_id")
);

CREATE TABLE "user_auth_accounts" (
    "auth_account_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "provider" VARCHAR(20) NOT NULL,
    "provider_subject" VARCHAR(255) NOT NULL,
    "password_hash" VARCHAR(255),
    "linked_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_USER_AUTH_ACCOUNTS" PRIMARY KEY ("auth_account_id"),
    CONSTRAINT "FK_users_TO_user_auth_accounts_1"
        FOREIGN KEY ("user_id") REFERENCES "users" ("user_id")
);

CREATE TABLE "user_terms_agreements" (
    "terms_type" VARCHAR(20) NOT NULL,
    "terms_version" VARCHAR(20) NOT NULL,
    "user_id" BIGINT NOT NULL,
    "agreed" BOOLEAN NOT NULL,
    "agreed_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_USER_TERMS_AGREEMENTS"
        PRIMARY KEY ("terms_type", "terms_version", "user_id"),
    CONSTRAINT "FK_users_TO_user_terms_agreements_1"
        FOREIGN KEY ("user_id") REFERENCES "users" ("user_id")
);

CREATE TABLE "refresh_tokens" (
    "token_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "token_hash" BYTEA NOT NULL CHECK (octet_length("token_hash") = 32),
    "device_name" VARCHAR(100),
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "revoked_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_REFRESH_TOKENS" PRIMARY KEY ("token_id"),
    CONSTRAINT "FK_users_TO_refresh_tokens_1"
        FOREIGN KEY ("user_id") REFERENCES "users" ("user_id")
);

CREATE TABLE "pages" (
    "page_id" UUID NOT NULL,
    "diary_id" UUID NOT NULL,
    "template_id" BIGINT,
    "template_config" JSONB,
    "title" VARCHAR(100),
    "sort_key" NUMERIC(20, 10) NOT NULL,
    "canvas_width" NUMERIC(10, 2) NOT NULL DEFAULT 1280.00,
    "canvas_height" NUMERIC(10, 2) NOT NULL DEFAULT 800.00,
    "grid_visible" BOOLEAN NOT NULL DEFAULT FALSE,
    "grid_color" CHAR(7),
    "version" BIGINT NOT NULL DEFAULT 1,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ(6),
    CONSTRAINT "PK_PAGES" PRIMARY KEY ("page_id"),
    CONSTRAINT "FK_diaries_TO_pages_1"
        FOREIGN KEY ("diary_id") REFERENCES "diaries" ("diary_id"),
    CONSTRAINT "FK_page_templates_TO_pages_1"
        FOREIGN KEY ("template_id") REFERENCES "page_templates" ("template_id")
);

CREATE TABLE "diary_members" (
    "diary_id" UUID NOT NULL,
    "user_id" BIGINT NOT NULL,
    "role" VARCHAR(20) NOT NULL,
    "member_color" CHAR(7) NOT NULL,
    "is_favorite" BOOLEAN NOT NULL DEFAULT FALSE,
    "last_opened_page_id" UUID,
    "last_opened_at" TIMESTAMPTZ(6),
    "joined_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "left_at" TIMESTAMPTZ(6),
    CONSTRAINT "PK_DIARY_MEMBERS" PRIMARY KEY ("diary_id", "user_id"),
    CONSTRAINT "FK_diaries_TO_diary_members_1"
        FOREIGN KEY ("diary_id") REFERENCES "diaries" ("diary_id"),
    CONSTRAINT "FK_users_TO_diary_members_1"
        FOREIGN KEY ("user_id") REFERENCES "users" ("user_id"),
    CONSTRAINT "FK_pages_TO_diary_members_1"
        FOREIGN KEY ("last_opened_page_id") REFERENCES "pages" ("page_id")
);

CREATE TABLE "diary_invites" (
    "invite_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "diary_id" UUID NOT NULL,
    "inviter_user_id" BIGINT NOT NULL,
    "invitee_user_id" BIGINT,
    "invite_type" VARCHAR(20) NOT NULL,
    "token_hash" BYTEA NOT NULL CHECK (octet_length("token_hash") = 32),
    "role" VARCHAR(20) NOT NULL DEFAULT 'EDITOR',
    "max_uses" INTEGER,
    "use_count" INTEGER NOT NULL DEFAULT 0,
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "revoked_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_DIARY_INVITES" PRIMARY KEY ("invite_id"),
    CONSTRAINT "FK_diaries_TO_diary_invites_1"
        FOREIGN KEY ("diary_id") REFERENCES "diaries" ("diary_id"),
    CONSTRAINT "FK_users_TO_diary_invites_1"
        FOREIGN KEY ("inviter_user_id") REFERENCES "users" ("user_id"),
    CONSTRAINT "FK_users_TO_diary_invites_2"
        FOREIGN KEY ("invitee_user_id") REFERENCES "users" ("user_id")
);

CREATE TABLE "diary_handwriting_fonts" (
    "diary_id" UUID NOT NULL,
    "font_media_file_id" UUID NOT NULL,
    "granted_by_user_id" BIGINT NOT NULL,
    "is_enabled" BOOLEAN NOT NULL DEFAULT TRUE,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "disabled_at" TIMESTAMPTZ(6),
    CONSTRAINT "PK_DIARY_HANDWRITING_FONTS"
        PRIMARY KEY ("diary_id", "font_media_file_id"),
    CONSTRAINT "FK_diaries_TO_diary_handwriting_fonts_1"
        FOREIGN KEY ("diary_id") REFERENCES "diaries" ("diary_id"),
    CONSTRAINT "FK_media_files_TO_diary_handwriting_fonts_1"
        FOREIGN KEY ("font_media_file_id") REFERENCES "media_files" ("media_file_id"),
    CONSTRAINT "FK_users_TO_diary_handwriting_fonts_1"
        FOREIGN KEY ("granted_by_user_id") REFERENCES "users" ("user_id")
);

CREATE TABLE "diary_media_library" (
    "diary_id" UUID NOT NULL,
    "media_file_id" UUID NOT NULL,
    "added_by_user_id" BIGINT NOT NULL,
    "library_category" VARCHAR(20) NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_DIARY_MEDIA_LIBRARY" PRIMARY KEY ("diary_id", "media_file_id"),
    CONSTRAINT "FK_diaries_TO_diary_media_library_1"
        FOREIGN KEY ("diary_id") REFERENCES "diaries" ("diary_id"),
    CONSTRAINT "FK_media_files_TO_diary_media_library_1"
        FOREIGN KEY ("media_file_id") REFERENCES "media_files" ("media_file_id"),
    CONSTRAINT "FK_users_TO_diary_media_library_1"
        FOREIGN KEY ("added_by_user_id") REFERENCES "users" ("user_id")
);

CREATE TABLE "canvas_elements" (
    "element_id" UUID NOT NULL,
    "page_id" UUID NOT NULL,
    "element_type" VARCHAR(20) NOT NULL,
    "group_id" UUID,
    "name" VARCHAR(100),
    "sort_key" NUMERIC(20, 10) NOT NULL,
    "x" NUMERIC(12, 3) NOT NULL,
    "y" NUMERIC(12, 3) NOT NULL,
    "width" NUMERIC(12, 3) NOT NULL,
    "height" NUMERIC(12, 3) NOT NULL,
    "rotation" NUMERIC(7, 3) NOT NULL DEFAULT 0,
    "opacity" NUMERIC(4, 3) NOT NULL DEFAULT 1.000,
    "is_locked" BOOLEAN NOT NULL DEFAULT FALSE,
    "is_hidden" BOOLEAN NOT NULL DEFAULT FALSE,
    "media_file_id" UUID,
    "properties_json" JSONB,
    "created_by" BIGINT,
    "version" BIGINT NOT NULL DEFAULT 1,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ(6),
    CONSTRAINT "PK_CANVAS_ELEMENTS" PRIMARY KEY ("element_id"),
    CONSTRAINT "FK_pages_TO_canvas_elements_1"
        FOREIGN KEY ("page_id") REFERENCES "pages" ("page_id"),
    CONSTRAINT "FK_media_files_TO_canvas_elements_1"
        FOREIGN KEY ("media_file_id") REFERENCES "media_files" ("media_file_id"),
    CONSTRAINT "FK_users_TO_canvas_elements_1"
        FOREIGN KEY ("created_by") REFERENCES "users" ("user_id")
);

CREATE TABLE "element_strokes" (
    "element_id" UUID NOT NULL,
    "tool" VARCHAR(20) NOT NULL,
    "pen_kind" VARCHAR(20),
    "color" CHAR(7) NOT NULL,
    "stroke_width" NUMERIC(8, 3) NOT NULL,
    "line_cap" VARCHAR(10) NOT NULL DEFAULT 'ROUND',
    "base_width" NUMERIC(12, 3) NOT NULL,
    "base_height" NUMERIC(12, 3) NOT NULL,
    "point_format" VARCHAR(30) NOT NULL DEFAULT 'JSON_V1',
    "points" JSONB NOT NULL,
    CONSTRAINT "PK_ELEMENT_STROKES" PRIMARY KEY ("element_id"),
    CONSTRAINT "FK_canvas_elements_TO_element_strokes_1"
        FOREIGN KEY ("element_id") REFERENCES "canvas_elements" ("element_id")
);

CREATE TABLE "canvas_history_operations" (
    "operation_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "page_id" UUID NOT NULL,
    "actor_user_id" BIGINT NOT NULL,
    "client_operation_id" UUID NOT NULL,
    "operation_type" VARCHAR(20) NOT NULL,
    "snapshot_format" VARCHAR(30) NOT NULL DEFAULT 'ELEMENTS_V1',
    "before_state_json" JSONB NOT NULL,
    "after_state_json" JSONB NOT NULL,
    "status" VARCHAR(20) NOT NULL DEFAULT 'APPLIED',
    "undone_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_CANVAS_HISTORY_OPERATIONS" PRIMARY KEY ("operation_id"),
    CONSTRAINT "FK_pages_TO_canvas_history_operations_1"
        FOREIGN KEY ("page_id") REFERENCES "pages" ("page_id"),
    CONSTRAINT "FK_users_TO_canvas_history_operations_1"
        FOREIGN KEY ("actor_user_id") REFERENCES "users" ("user_id")
);

CREATE TABLE "notifications" (
    "notification_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "actor_user_id" BIGINT,
    "diary_id" UUID,
    "page_id" UUID,
    "notification_type" VARCHAR(50) NOT NULL,
    "payload_json" JSONB,
    "read_at" TIMESTAMPTZ(6),
    "deleted_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_NOTIFICATIONS" PRIMARY KEY ("notification_id"),
    CONSTRAINT "FK_users_TO_notifications_1"
        FOREIGN KEY ("user_id") REFERENCES "users" ("user_id"),
    CONSTRAINT "FK_users_TO_notifications_2"
        FOREIGN KEY ("actor_user_id") REFERENCES "users" ("user_id"),
    CONSTRAINT "FK_diaries_TO_notifications_1"
        FOREIGN KEY ("diary_id") REFERENCES "diaries" ("diary_id"),
    CONSTRAINT "FK_pages_TO_notifications_1"
        FOREIGN KEY ("page_id") REFERENCES "pages" ("page_id")
);

CREATE TABLE "ai_jobs" (
    "ai_job_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "job_type" VARCHAR(30) NOT NULL DEFAULT 'BACKGROUND_REMOVAL',
    "source_media_file_id" UUID NOT NULL,
    "result_media_file_id" UUID,
    "status" VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    "error_code" VARCHAR(50),
    "error_message" VARCHAR(500),
    "requested_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "started_at" TIMESTAMPTZ(6),
    "completed_at" TIMESTAMPTZ(6),
    CONSTRAINT "PK_AI_JOBS" PRIMARY KEY ("ai_job_id"),
    CONSTRAINT "FK_media_files_TO_ai_jobs_1"
        FOREIGN KEY ("source_media_file_id") REFERENCES "media_files" ("media_file_id"),
    CONSTRAINT "FK_media_files_TO_ai_jobs_2"
        FOREIGN KEY ("result_media_file_id") REFERENCES "media_files" ("media_file_id")
);

COMMENT ON TABLE "users" IS '회원';
COMMENT ON COLUMN "users"."user_id" IS '회원 ID (자동 증가)';
COMMENT ON COLUMN "users"."email" IS '이메일';
COMMENT ON COLUMN "users"."nickname" IS '닉네임';
COMMENT ON COLUMN "users"."profile_img" IS '프로필 색상';
COMMENT ON COLUMN "users"."status" IS 'ACTIVE | SUSPENDED | WITHDRAWN';
COMMENT ON COLUMN "users"."last_login_at" IS '마지막 로그인 시각';
COMMENT ON COLUMN "users"."created_at" IS '가입 시각';
COMMENT ON COLUMN "users"."updated_at" IS '수정 시각';
COMMENT ON COLUMN "users"."deleted_at" IS '탈퇴 시각';

COMMENT ON COLUMN "page_templates"."template_id" IS '속지 ID (자동 증가)';
COMMENT ON COLUMN "page_templates"."code" IS '앱 속지 식별자';
COMMENT ON COLUMN "page_templates"."template_version" IS '속지 버전';
COMMENT ON COLUMN "page_templates"."name" IS '표시 이름';
COMMENT ON COLUMN "page_templates"."category" IS 'BLANK | LINED | SQUARED | DOTTED | MONTHLY | WEEKLY | DAILY | DIVIDER | COVER';
COMMENT ON COLUMN "page_templates"."orientation" IS '용지 방향';
COMMENT ON COLUMN "page_templates"."canvas_width" IS '속지 기준 너비';
COMMENT ON COLUMN "page_templates"."canvas_height" IS '속지 기준 높이';
COMMENT ON COLUMN "page_templates"."default_config" IS '속지 기본 설정';
COMMENT ON COLUMN "page_templates"."display_order" IS '표시 순서';
COMMENT ON COLUMN "page_templates"."is_active" IS '노출 여부';
COMMENT ON COLUMN "page_templates"."created_at" IS '생성 시각';
COMMENT ON COLUMN "page_templates"."updated_at" IS '수정 시각';

COMMENT ON COLUMN "diaries"."diary_id" IS '다이어리 ID (앱 생성 UUID)';
COMMENT ON COLUMN "diaries"."owner_user_id" IS '회원 소유자 ID. 비회원 데이터 이관 전에는 NULL';
COMMENT ON COLUMN "diaries"."owner_device_id" IS '소유 기기 ID. 회원 계정 이관용으로 유지';
COMMENT ON COLUMN "diaries"."title" IS '다이어리 제목';
COMMENT ON COLUMN "diaries"."cover_color" IS '표지 색상 #RRGGBB';
COMMENT ON COLUMN "diaries"."cover_style" IS '표지 스타일';
COMMENT ON COLUMN "diaries"."visibility" IS 'PRIVATE | MEMBERS | LINK';
COMMENT ON COLUMN "diaries"."created_at" IS '생성 시각';
COMMENT ON COLUMN "diaries"."updated_at" IS '마지막 수정 시각';
COMMENT ON COLUMN "diaries"."deleted_at" IS '휴지통 이동 시각';

COMMENT ON TABLE "media_files" IS '미디어 파일';
COMMENT ON COLUMN "media_files"."media_file_id" IS '미디어 ID (앱 생성 UUID)';
COMMENT ON COLUMN "media_files"."owner_user_id" IS '회원 소유자 ID';
COMMENT ON COLUMN "media_files"."owner_device_id" IS '소유 기기 ID. 회원 계정 이관용으로 유지';
COMMENT ON COLUMN "media_files"."media_type" IS 'IMAGE | FONT';
COMMENT ON COLUMN "media_files"."source_type" IS 'UPLOAD | AI_RESULT';
COMMENT ON COLUMN "media_files"."source_media_file_id" IS 'AI 결과의 원본 사진 ID';
COMMENT ON COLUMN "media_files"."library_category" IS 'PHOTO | STICKER | TAPE';
COMMENT ON COLUMN "media_files"."storage_key" IS '파일 저장소 경로';
COMMENT ON COLUMN "media_files"."original_filename" IS '원본 파일명';
COMMENT ON COLUMN "media_files"."mime_type" IS 'MIME 타입';
COMMENT ON COLUMN "media_files"."file_size" IS '바이트 크기';
COMMENT ON COLUMN "media_files"."width" IS '이미지 너비(px)';
COMMENT ON COLUMN "media_files"."height" IS '이미지 높이(px)';
COMMENT ON COLUMN "media_files"."checksum_sha256" IS '파일 해시';
COMMENT ON COLUMN "media_files"."status" IS 'UPLOADING | READY | FAILED';
COMMENT ON COLUMN "media_files"."created_at" IS '생성 시각';
COMMENT ON COLUMN "media_files"."deleted_at" IS '삭제 시각';

COMMENT ON TABLE "user_auth_accounts" IS '로그인 계정';
COMMENT ON COLUMN "user_auth_accounts"."auth_account_id" IS '인증 계정 ID (자동 증가)';
COMMENT ON COLUMN "user_auth_accounts"."user_id" IS '회원 ID';
COMMENT ON COLUMN "user_auth_accounts"."provider" IS '로그인 제공자 (EMAIL, GOOGLE 등)';
COMMENT ON COLUMN "user_auth_accounts"."provider_subject" IS '제공자 쪽 사용자 식별값';
COMMENT ON COLUMN "user_auth_accounts"."password_hash" IS '이메일 로그인 비밀번호 해시';
COMMENT ON COLUMN "user_auth_accounts"."linked_at" IS '연결 시각';

COMMENT ON TABLE "user_terms_agreements" IS '약관 동의';
COMMENT ON COLUMN "user_terms_agreements"."terms_type" IS '약관 종류';
COMMENT ON COLUMN "user_terms_agreements"."terms_version" IS '약관 버전';
COMMENT ON COLUMN "user_terms_agreements"."user_id" IS '회원 ID';
COMMENT ON COLUMN "user_terms_agreements"."agreed" IS '동의 여부';
COMMENT ON COLUMN "user_terms_agreements"."agreed_at" IS '동의 시각';

COMMENT ON TABLE "refresh_tokens" IS '리프레시 토큰';
COMMENT ON COLUMN "refresh_tokens"."token_id" IS '토큰 ID (자동 증가)';
COMMENT ON COLUMN "refresh_tokens"."user_id" IS '회원 ID';
COMMENT ON COLUMN "refresh_tokens"."token_hash" IS '리프레시 토큰 해시 (SHA-256, 32바이트)';
COMMENT ON COLUMN "refresh_tokens"."device_name" IS '로그인 기기 이름';
COMMENT ON COLUMN "refresh_tokens"."expires_at" IS '만료 시각';
COMMENT ON COLUMN "refresh_tokens"."revoked_at" IS '폐기 시각';
COMMENT ON COLUMN "refresh_tokens"."created_at" IS '발급 시각';

COMMENT ON COLUMN "pages"."page_id" IS '페이지 ID (앱 생성 UUID)';
COMMENT ON COLUMN "pages"."diary_id" IS '다이어리 ID';
COMMENT ON COLUMN "pages"."template_id" IS '속지 ID. NULL 이면 흰 종이';
COMMENT ON COLUMN "pages"."template_config" IS '페이지별 속지 설정';
COMMENT ON COLUMN "pages"."title" IS '페이지 제목';
COMMENT ON COLUMN "pages"."sort_key" IS '페이지 순서';
COMMENT ON COLUMN "pages"."canvas_width" IS '페이지 논리 너비';
COMMENT ON COLUMN "pages"."canvas_height" IS '페이지 논리 높이';
COMMENT ON COLUMN "pages"."grid_visible" IS '격자 가이드 표시';
COMMENT ON COLUMN "pages"."grid_color" IS '격자 가이드 색상';
COMMENT ON COLUMN "pages"."version" IS '낙관적 잠금 버전';
COMMENT ON COLUMN "pages"."created_at" IS '생성 시각';
COMMENT ON COLUMN "pages"."updated_at" IS '수정 시각';
COMMENT ON COLUMN "pages"."deleted_at" IS '삭제 시각';

COMMENT ON TABLE "diary_members" IS '다이어리 멤버';
COMMENT ON COLUMN "diary_members"."diary_id" IS '다이어리 ID';
COMMENT ON COLUMN "diary_members"."user_id" IS '회원 ID';
COMMENT ON COLUMN "diary_members"."role" IS 'OWNER | EDITOR | VIEWER';
